      const state2 = { fillShow: 0.58, squash: 0, punchT: null, coins: [] };
      const model2 = painter.sackGeometry(state2, "home");
      const pitch = 76 * Math.PI / 180;
      const rotate = ([x2, y2, z]) => {
        const across = (x2 - y2) / Math.SQRT2;
        const depth = (x2 + y2) / Math.SQRT2;
        const tilted = depth * Math.cos(pitch) - z * Math.sin(pitch);
        return [
          (tilted + across) / Math.SQRT2,
          (tilted - across) / Math.SQRT2,
          depth * Math.sin(pitch) + z * Math.cos(pitch)
        ];
      };
